// True while the person asks for reduced motion (prefers-reduced-motion: reduce), and on the server.
// Shared by the units that animate content rather than state: Chart and Marquee.
import { useSyncExternalStore } from "react";

const QUERY = "(prefers-reduced-motion: reduce)";
const read = () => typeof matchMedia === "function" && matchMedia(QUERY).matches;
const subscribe = (on: () => void) => {
  if (typeof matchMedia !== "function") return () => {};
  const m = matchMedia(QUERY);
  m.addEventListener("change", on);
  return () => m.removeEventListener("change", on);
};

export function useReducedMotion(): boolean {
  return useSyncExternalStore(subscribe, read, () => true);
}
